        {
            $program = [
                ['opcode' => 'OpenRead', 'source' => 'partial-expression-index', 'rootPage' => $plan['rootPage'] ?? null],
                ['opcode' => 'RewindOrArm', 'armCount' => $plan['orArmCount'] ?? 0],
