                    'expression' => $expression,
                    'expressionColumn' => (string) ($index['expressionColumn'] ?? ''),
                    'collation' => strtoupper((string) ($index['collation'] ?? 'BINARY')),
                    'coveringColumns' => self::stringListForLikePrefixWindow($index['coveringColumns'] ?? []),
                    'covering' => $covering,
                    'partialPredicateTerms' => $partial,
                    'partialPredicateImplied' => $partialImplied,
                    'stat4Samples' => $stat4,
                    'stat4Used' => $stat4 !== [],
                    'prefix' => $prefix,
                    'prefixUpperBound' => $upper,
                    'stat4PrefixWindow' => $window,
                    'matchedRows' => $matchedRows,
                    'estimatedRows' => max(1, count($matchedRows)),
                    'estimatedCost' => max(1, count($matchedRows) + ($covering ? 0 : 12) + ($window === [] ? 40 : 0)),
                    'detail' => 'SEARCH ' . self::stringValueLikePrefixWindow($index, 'name') . ' USING STAT4 EXPRESSION PARTIAL LIKE PREFIX WINDOW',
                ];
                if ($best === null || [
                    $plan['usable'] ? 0 : 1,
                    $plan['estimatedCost'],
                    $plan['name'],
                ] < [
                    $best['usable'] ? 0 : 1,
                    $best['estimatedCost'],
                    $best['name'],
                ]) {
                    $best = $plan;
                }
            }

            return $best ?? ['usable' => false, 'matchedRows' => [], 'stat4Used' => false, 'partialPredicateImplied' => false];
        }

        /** @param list<array<string,mixed>> $terms */
        private static function likePrefixWindowTermPrefix(array $terms, string $expression): ?string
        {
            $normalized = self::normalizeLikePrefixWindowExpression($expression);
            foreach ($terms as $term) {
                if (self::normalizeLikePrefixWindowExpression((string) ($term['left']['expression'] ?? '')) !== $normalized) {
                    continue;
                }
                if (strtoupper((string) ($term['operator'] ?? '')) !== 'LIKE') {
                    continue;
                }
                $pattern = self::literalForLikePrefixWindow($term['right'] ?? null);
                if (!is_string($pattern)) {
                    return null;
                }
                $escape = $term['escape'] ?? '\\';
                if (!is_string($escape) || strlen($escape) !== 1) {
                    throw new \InvalidArgumentException('SQLite next175 LIKE escape must be one byte');
                }

                return self::literalPrefixForLikePrefixWindow($pattern, $escape);
            }

            return null;
        }

        private static function literalPrefixForLikePrefixWindow(string $pattern, string $escape): ?string
        {
            $prefix = '';
            $length = strlen($pattern);
            for ($i = 0; $i < $length; $i++) {
                $char = $pattern[$i];
                if ($char === $escape) {
                    $i++;
                    if ($i >= $length) {
                        return null;
                    }
                    $prefix .= $pattern[$i];
                    continue;
                }
                if ($char === '%' || $char === '_') {
                    return $prefix === '' ? null : $prefix;
                }
                $prefix .= $char;
            }

            return null;
        }

        private static function likePrefixWindowUpperBound(string $prefix): ?string
        {
            if ($prefix === '') {
                return null;
            }
            $last = ord($prefix[strlen($prefix) - 1]);
            if ($last >= 0x7f) {
                return null;
            }

            return substr($prefix, 0, -1) . chr($last + 1);
        }

        /**
         * @param list<array<string,mixed>> $samples
         * @return array{lower:string,upper:string,samples:list<array<string,mixed>>,rowids:list<int>,keys:list<mixed>}|array{}
         */
        private static function stat4LikePrefixWindow(array $samples, string $prefix, string $upper, string $collation): array
        {
            $matched = [];
            foreach ($samples as $sample) {
                if (self::compareForLikePrefixWindow($sample['key'], $prefix, $collation) >= 0 && self::compareForLikePrefixWindow($sample['key'], $upper, $collation) < 0) {
                    $matched[] = $sample;
                }
            }
            if ($matched === []) {
                return [];
            }

            return [
                'lower' => $prefix,
                'upper' => $upper,
                'samples' => $matched,
                'rowids' => array_column($matched, 'rowid'),
                'keys' => array_column($matched, 'key'),
            ];
        }

        /**
         * @param list<array<string,mixed>> $terms
         * @return list<array<string,mixed>>
         */
        private static function matchedRowsForLikePrefixWindow(array $source, array $terms, string $expression, string $collation): array
        {
            $rows = [];
            foreach (self::listValueLikePrefixWindow($source['rows'] ?? []) as $row) {
                if (!is_array($row)) {
                    throw new \InvalidArgumentException('SQLite next175 rows must be arrays');
                }
                $rowid = $row['rowid'] ?? null;
                if (!is_int($rowid) || $rowid < 0) {
                    throw new \InvalidArgumentException('SQLite next175 rowid must be a non-negative integer');
                }
                if (!self::rowSatisfiesLikePrefixWindowTerms($row, $terms, $expression, $collation)) {
                    continue;
                }
                $rows[] = [
                    'rowid' => $rowid,
                    'expressionKey' => self::expressionValueLikePrefixWindow($row, $expression),
                    'payload' => $row,
                ];
            }
            usort($rows, static fn (array $a, array $b): int => self::compareForLikePrefixWindow($a['expressionKey'] ?? null, $b['expressionKey'] ?? null, $collation)
                ?: ((int) ($a['rowid'] ?? 0) <=> (int) ($b['rowid'] ?? 0)));

            return $rows;
        }

        /** @param list<array<string,mixed>> $terms */
        private static function rowSatisfiesLikePrefixWindowTerms(array $row, array $terms, string $expression, string $collation): bool
        {
            foreach ($terms as $term) {
                $operator = strtoupper((string) ($term['operator'] ?? ''));
                $left = $term['left'] ?? null;
                if (!is_array($left)) {
                    return false;
                }
                $value = array_key_exists('expression', $left)
                    ? self::expressionValueLikePrefixWindow($row, (string) $left['expression'])
                    : ($row[(string) ($left['column'] ?? '')] ?? null);
                if ($operator === '=' && self::compareForLikePrefixWindow($value, self::literalForLikePrefixWindow($term['right'] ?? null), $collation) !== 0) {
                    return false;
                }
                if ($operator === 'LIKE') {
                    $prefix = self::literalPrefixForLikePrefixWindow((string) self::literalForLikePrefixWindow($term['right'] ?? null), (string) ($term['escape'] ?? '\\'));
                    if ($prefix === null || !is_string($value) || !str_starts_with($value, $prefix)) {
                        return false;
                    }
                }
                if ($operator === 'IS NOT NULL' && $value === null) {
                    return false;
                }
                if (in_array($operator, ['>', '>=', '<', '<='], true)) {
                    $comparison = self::compareForLikePrefixWindow($value, self::literalForLikePrefixWindow($term['right'] ?? null), $collation);
                    if (($operator === '>' && $comparison <= 0)
                        || ($operator === '>=' && $comparison < 0)
                        || ($operator === '<' && $comparison >= 0)
                        || ($operator === '<=' && $comparison > 0)) {
                        return false;
                    }
                }
            }

            return true;
        }

        /**
         * @param list<array<string,mixed>> $partialTerms
         * @param list<array<string,mixed>> $terms
         */
        private static function likePrefixWindowPartialPredicateImplied(array $partialTerms, array $terms): bool
        {
            foreach ($partialTerms as $partial) {
                if (!is_array($partial)) {
                    return false;
                }
                $matched = false;
                foreach ($terms as $term) {
                    if (is_array($term) && self::termImpliesLikePrefixWindowPartial($term, $partial)) {
                        $matched = true;
                        break;
                    }
                }
                if (!$matched) {
                    return false;
                }
            }

            return true;
        }

        private static function termImpliesLikePrefixWindowPartial(array $term, array $partial): bool
        {
            if (self::leftKeyForLikePrefixWindow($term['left'] ?? null) !== self::leftKeyForLikePrefixWindow($partial['left'] ?? null)) {
                return false;
            }
            $operator = strtoupper((string) ($term['operator'] ?? ''));
            $partialOperator = strtoupper((string) ($partial['operator'] ?? ''));
            if ($partialOperator === 'IS NOT NULL') {
                return $operator !== 'IS NULL';
            }
            if ($operator === $partialOperator && self::literalForLikePrefixWindow($term['right'] ?? null) === self::literalForLikePrefixWindow($partial['right'] ?? null)) {
                return true;
            }
            if ($operator === 'LIKE' && in_array($partialOperator, ['>=', '<'], true)) {
                $prefix = self::likePrefixWindowTermPrefix([$term], (string) ($term['left']['expression'] ?? ''));
                if ($prefix === null) {
                    return false;
                }
                $bound = (string) self::literalForLikePrefixWindow($partial['right'] ?? null);

                return $partialOperator === '>='
                    ? self::compareForLikePrefixWindow($prefix, $bound, 'BINARY') >= 0
                    : self::compareForLikePrefixWindow((string) self::likePrefixWindowUpperBound($prefix), $bound, 'BINARY') <= 0;
            }

            return false;
        }

        private static function leftKeyForLikePrefixWindow(mixed $left): string
        {
            if (!is_array($left)) {
                return '';
            }
            if (array_key_exists('expression', $left)) {
                return 'expr:' . self::normalizeLikePrefixWindowExpression((string) $left['expression']);
            }

            return 'col:' . strtolower((string) ($left['column'] ?? ''));
        }

        /**
         * @param list<array<string,mixed>> $samples
         * @return list<array{key:mixed,rowid:int,neq:int,nlt:int,ndlt:int}>
         */
        private static function stat4SamplesForLikePrefixWindow(array $samples): array
        {
            $out = [];
            foreach ($samples as $sample) {
                if (!is_array($sample) || !is_array($sample['sample'] ?? null) || count($sample['sample']) < 2) {
                    throw new \InvalidArgumentException('SQLite next175 STAT4 samples need key and rowid');
                }
                $out[] = [
                    'key' => $sample['sample'][0],
                    'rowid' => self::intValueLikePrefixWindow($sample['sample'][1]),
                    'neq' => self::firstStatIntForLikePrefixWindow($sample['neq'] ?? 1),
                    'nlt' => self::firstStatIntForLikePrefixWindow($sample['nlt'] ?? 0),
                    'ndlt' => self::firstStatIntForLikePrefixWindow($sample['ndlt'] ?? 0),
                ];
            }
            usort($out, static fn (array $a, array $b): int => self::compareForLikePrefixWindow($a['key'], $b['key'], 'BINARY')
                ?: ($a['rowid'] <=> $b['rowid']));

            return $out;
        }

        private static function expressionValueLikePrefixWindow(array $row, string $expression): mixed
        {
            $normalized = self::normalizeLikePrefixWindowExpression($expression);
            if ($normalized === 'lower(option_name)') {
                $value = $row['option_name'] ?? null;

                return is_string($value) ? strtolower($value) : null;
            }
            if ($normalized === 'length(option_value)') {
                $value = $row['option_value'] ?? null;

                return is_string($value) ? strlen($value) : null;
            }

            return $row[$normalized] ?? null;
        }

        private static function normalizeLikePrefixWindowExpression(string $expression): string
        {
            return strtolower((string) preg_replace('/\s+/', '', $expression));
        }

        private static function compareForLikePrefixWindow(mixed $left, mixed $right, string $collation): int
        {
            if ($left === $right) {
                return 0;
            }
            if ($left === null) {
                return -1;
            }
            if ($right === null) {
                return 1;
            }
            if (is_numeric($left) && is_numeric($right)) {
                return (float) $left <=> (float) $right;
            }
            $leftString = (string) $left;
            $rightString = (string) $right;
            if (strtoupper($collation) === 'NOCASE') {
                $leftString = strtolower($leftString);
                $rightString = strtolower($rightString);
            }

            return $leftString <=> $rightString;
        }

        private static function literalForLikePrefixWindow(mixed $value): mixed
        {
            if (is_array($value) && array_key_exists('literal', $value)) {
                return $value['literal'];
            }

            return $value;
        }

        /** @return list<mixed> */
        private static function listValueLikePrefixWindow(mixed $value): array
        {
            return is_array($value) ? array_values($value) : [];
        }

        /** @return list<string> */
        private static function stringListForLikePrefixWindow(mixed $value): array
        {
            return array_values(array_map('strval', self::listValueLikePrefixWindow($value)));
        }

        private static function stringValueLikePrefixWindow(array $array, string $key): string
        {
            if (!isset($array[$key]) || !is_scalar($array[$key])) {
                throw new \InvalidArgumentException('SQLite next175 missing string ' . $key);
            }

            return (string) $array[$key];
        }

        private static function intValueLikePrefixWindow(mixed $value): int
        {
            if (!is_int($value) && !ctype_digit((string) $value)) {
                throw new \InvalidArgumentException('SQLite next175 integer value expected');
            }

            return (int) $value;
        }

        private static function firstStatIntForLikePrefixWindow(mixed $value): int
        {
            if (is_int($value)) {
                return $value;
            }
            $parts = preg_split('/\s+/', trim((string) $value));
            if ($parts === false || $parts === [] || !ctype_digit($parts[0])) {
                throw new \InvalidArgumentException('SQLite next175 STAT4 counters must be numeric');
            }

            return (int) $parts[0];
        }

        private static function likePrefixWindowSignature(mixed $value): string
        {
            return hash('sha256', json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES));
        }

        /** @param list<string> $neededColumns */
        private static function coversLikePrefixWindowColumns(mixed $coveringColumns, array $neededColumns): bool
        {
            $covering = array_map('strtolower', self::stringListForLikePrefixWindow($coveringColumns));
            foreach ($neededColumns as $column) {
                if (!in_array(strtolower($column), $covering, true)) {
                    return false;
                }
            }

            return true;
        }

        /** @return array<string,mixed> */
        private static function likePrefixWindowSummary(array $source, array $plan, string $sourceSignature): array
        {
            return [
                'source' => $source['name'] ?? null,
                'schemaCookie' => self::intValueLikePrefixWindow($source['schemaCookie'] ?? null),
                'stat4Generation' => self::intValueLikePrefixWindow($source['stat4Generation'] ?? null),
                'sourceSignature' => $sourceSignature,
                'usable' => $plan['usable'] ?? false,
                'name' => $plan['name'] ?? null,
                'rootPage' => $plan['rootPage'] ?? null,
                'prefix' => $plan['prefix'] ?? null,
                'prefixUpperBound' => $plan['prefixUpperBound'] ?? null,
                'matchedRowids' => array_column($plan['matchedRows'] ?? [], 'rowid'),
                'partialPredicateImplied' => $plan['partialPredicateImplied'] ?? false,
                'stat4Used' => $plan['stat4Used'] ?? false,
                'stat4PrefixWindow' => $plan['stat4PrefixWindow'] ?? [],
            ];
        }

        /** @return array<string,mixed> */
        private static function selectedLikePrefixWindowSummary(array $selected, bool $ready): array
        {
            return [
                'ready' => $ready,
                'usable' => $selected['usable'] ?? false,
                'name' => $selected['name'] ?? null,
                'rootPage' => $selected['rootPage'] ?? null,
                'expression' => $selected['expression'] ?? null,
                'expressionColumn' => $selected['expressionColumn'] ?? null,
                'collation' => $selected['collation'] ?? null,
                'covering' => $selected['covering'] ?? false,
                'partialPredicateImplied' => $selected['partialPredicateImplied'] ?? false,
                'stat4Used' => $selected['stat4Used'] ?? false,
                'prefix' => $selected['prefix'] ?? null,
                'prefixUpperBound' => $selected['prefixUpperBound'] ?? null,
                'estimatedRows' => $selected['estimatedRows'] ?? null,
                'estimatedCost' => $selected['estimatedCost'] ?? null,
                'detail' => $selected['detail'] ?? null,
            ];
        }

        /** @return list<array<string,mixed>> */
        private static function likePrefixWindowCursorProgram(array $selected, bool $ready): array
        {
            if (!$ready) {
                return [['opcode' => 'FallbackFullScan', 'reason' => 'STAT4 LIKE prefix window not usable']];
            }
            $program = [
                ['opcode' => 'OpenRead', 'source' => 'partial-expression-index', 'rootPage' => $selected['rootPage'] ?? null],
                ['opcode' => 'FenceStat4PrefixWindow', 'window' => $selected['stat4PrefixWindow'] ?? []],
                ['opcode' => 'SeekGE', 'key' => $selected['prefix'] ?? null],
                ['opcode' => 'IdxGE', 'key' => $selected['prefixUpperBound'] ?? null],
                ['opcode' => 'ResidualLikePrefix', 'prefix' => $selected['prefix'] ?? null],
            ];
            $program[] = ($selected['covering'] ?? false)
                ? ['opcode' => 'ColumnFromIndex', 'columns' => $selected['coveringColumns'] ?? []]
                : ['opcode' => 'DeferredSeek', 'table' => 'app_settings'];
            $program[] = ['opcode' => 'ResultRow', 'rowids' => array_column($selected['matchedRows'] ?? [], 'rowid')];
            $program[] = ['opcode' => 'Next', 'source' => 'partial-expression-index'];

            return $program;
        }

    /* Variant formerly implemented by SQLitePlannerStat4ExpressionPartialCurrentSourceNextPlan. */

    /**
         * @param array<string,mixed> $preparedSource
         * @param array<string,mixed> $currentSource
         * @param list<array<string,mixed>> $whereTerms
         * @param list<string> $neededColumns
         * @return array<string,mixed>
         */
        public static function materializeStat4BoundaryRangeAudit(array $preparedSource, array $currentSource, array $whereTerms, array $neededColumns): array
        {
            $base = SQLitePlannerStat4ExpressionPartialCurrentSourceNextPlan::materializeStat4CurrentRange(
                $preparedSource,
                $currentSource,
                $whereTerms,
                $neededColumns,
            );
            $selected = self::arrayValueForStat4BoundaryRangeAudit($base, 'selectedPlan');
            $range = self::arrayValueForStat4BoundaryRangeAudit($selected, 'rangeConstraint');
            $boundary = self::rangeBoundaryForStat4BoundaryRangeAudit($range);
            $ready = ($base['status'] ?? null) === 'stat4-expression-partial-current-source-stat4-current-range-ready'
                && ($selected['partialPredicateImpliedByRange'] ?? false) === true
                && ($selected['stat4Used'] ?? false) === true
                && ($selected['matchedRowCount'] ?? 0) > 0
                && ($boundary['usesExactBoundaryOpcodes'] ?? false) === true
                && self::rowBoundaryAuditForStat4BoundaryRangeAudit(self::listValueForStat4BoundaryRangeAudit($base['matchedRows'] ?? []), $range, (string) ($selected['collation'] ?? 'BINARY'))['leakedRowids'] === [];

            $audit = self::rowBoundaryAuditForStat4BoundaryRangeAudit(self::listValueForStat4BoundaryRangeAudit($base['matchedRows'] ?? []), $range, (string) ($selected['collation'] ?? 'BINARY'));

            return array_replace($base, [
                'status' => $ready ? 'stat4-expression-partial-current-source-next176-ready' : 'requires-next-stage',
                'rangeBoundary' => $boundary,
                'boundaryRowAudit' => $audit,
                'cursorProgram' => self::cursorProgramForStat4BoundaryRangeAudit($selected, $boundary, $audit, $ready),
                'selectedPlan' => array_replace($selected, [
                    'next176Ready' => $ready,
                    'next176SeekOpcode' => $boundary['lowerSeekOpcode'],
                    'next176UpperFenceOpcode' => $boundary['upperFenceOpcode'],
                    'next176BoundarySignature' => self::signatureForStat4BoundaryRangeAudit([$boundary, $audit['acceptedRowids']]),
                ]),
                'stat4Fence' => array_replace(self::arrayValueForStat4BoundaryRangeAudit($base, 'stat4Fence'), [
                    'next176BoundarySignature' => self::signatureForStat4BoundaryRangeAudit([$boundary, $audit['acceptedRowids']]),
                    'next176AcceptedRowids' => $audit['acceptedRowids'],
                ]),
                'detail' => (($base['reprepareRequired'] ?? false) ? 'REPREPARE' : 'REUSE')
                    . ' STAT4 EXPRESSION PARTIAL CURRENT SOURCE NEXT176 EXACT RANGE BOUNDARIES '
                    . (string) ($selected['name'] ?? 'NO INDEX'),
                'dependencies' => array_values(array_unique(array_merge(
                    is_array($base['dependencies'] ?? null) ? $base['dependencies'] : [],
                    [
                        'SQLitePlannerStat4ExpressionPartialCurrentSourceNextPlan',
                        'sqlite-sqlplanner-stat4-expression-partial-current-source-next176',
                    ],
                ))),
                'dependency_closure' => 'no new support component needed; next176 reuses native STAT4 expression partial current-source planning and adds exact lower/upper range-bound cursor opcodes',
                'non_overlap' => 'avoids accepted next173 duplicate STAT4 sample fanout, next172 selectivity refresh, next168 LIKE prefix conversion, expression ORDER BY, range-cost, JSON, WAL, VFS, and B-tree clusters; this slice only fixes exact exclusive/inclusive expression range cursor boundaries',
            ]);
        }

        /**
         * @param array<string,mixed> $range
         * @return array<string,mixed>
         */
        private static function rangeBoundaryForStat4BoundaryRangeAudit(array $range): array
        {
            $lowerInclusive = (bool) ($range['lowerInclusive'] ?? false);
            $upperInclusive = (bool) ($range['upperInclusive'] ?? false);

            return [
                'lowerKey' => $range['lower'] ?? null,
                'upperKey' => $range['upper'] ?? null,
                'lowerInclusive' => $lowerInclusive,
                'upperInclusive' => $upperInclusive,
                'lowerSeekOpcode' => $lowerInclusive ? 'SeekGE' : 'SeekGT',
                'upperFenceOpcode' => $upperInclusive ? 'IdxLE' : 'IdxLT',
                'usesExactBoundaryOpcodes' => true,
            ];
        }

        /**
         * @param list<array<string,mixed>> $matchedRows
         * @param array<string,mixed> $range
         * @return array{acceptedRowids:list<int>,acceptedKeys:list<mixed>,leakedRowids:list<int>,lowerEdgeRowids:list<int>,upperEdgeRowids:list<int>,signature:string}
         */
        private static function rowBoundaryAuditForStat4BoundaryRangeAudit(array $matchedRows, array $range, string $collation): array
        {
            $accepted = [];
            $leaked = [];
            $lowerEdge = [];
            $upperEdge = [];
            foreach ($matchedRows as $row) {
                if (!is_array($row)) {
                    throw new \InvalidArgumentException('SQLite next176 matched rows must be arrays');
                }
                $rowid = self::intValueForStat4BoundaryRangeAudit($row['rowid'] ?? null);
                $key = $row['expressionKey'] ?? null;
                $lower = self::compareForStat4BoundaryRangeAudit($key, $range['lower'] ?? null, $collation);
                $upper = self::compareForStat4BoundaryRangeAudit($key, $range['upper'] ?? null, $collation);
                $inside = (($range['lowerInclusive'] ?? false) ? $lower >= 0 : $lower > 0)
                    && (($range['upperInclusive'] ?? false) ? $upper <= 0 : $upper < 0);
                if ($lower === 0) {
                    $lowerEdge[] = $rowid;
                }
                if ($upper === 0) {
                    $upperEdge[] = $rowid;
                }
                if ($inside) {
                    $accepted[] = ['rowid' => $rowid, 'key' => $key];
                } else {
                    $leaked[] = $rowid;
                }
            }

            return [
                'acceptedRowids' => array_column($accepted, 'rowid'),
                'acceptedKeys' => array_column($accepted, 'key'),
                'leakedRowids' => $leaked,
                'lowerEdgeRowids' => $lowerEdge,
                'upperEdgeRowids' => $upperEdge,
                'signature' => self::signatureForStat4BoundaryRangeAudit($accepted),
            ];
        }

        /**
         * @param array<string,mixed> $selected
         * @param array<string,mixed> $boundary
         * @param array<string,mixed> $audit
         * @return list<array<string,mixed>>
         */
        private static function cursorProgramForStat4BoundaryRangeAudit(array $selected, array $boundary, array $audit, bool $ready): array
        {
            if (!$ready) {
                return [['opcode' => 'FallbackFullScan', 'reason' => 'exact STAT4 expression partial range boundaries not usable']];
            }

            return [
                ['opcode' => 'OpenRead', 'rootPage' => $selected['rootPage'] ?? null, 'index' => $selected['name'] ?? null],
                ['opcode' => 'FenceExactRangeBoundary', 'signature' => $audit['signature']],
                ['opcode' => $boundary['lowerSeekOpcode'], 'key' => $boundary['lowerKey']],
                ['opcode' => $boundary['upperFenceOpcode'], 'key' => $boundary['upperKey']],
                ['opcode' => (($selected['covering'] ?? false) ? 'ColumnFromIndex' : 'DeferredSeek')],
                ['opcode' => 'ResidualPartialCheck'],
                ['opcode' => 'ResultRow', 'rowids' => $audit['acceptedRowids']],
                ['opcode' => 'Next'],
            ];
        }

        /** @return array<string,mixed> */
        private static function arrayValueForStat4BoundaryRangeAudit(array $array, string $key): array
        {
            $value = $array[$key] ?? null;
            if (!is_array($value)) {
                throw new \InvalidArgumentException('SQLite next176 needs array ' . $key);
            }

            return $value;
        }

        /** @return list<mixed> */
        private static function listValueForStat4BoundaryRangeAudit(mixed $value): array
        {
            return is_array($value) ? array_values($value) : [];
        }

        private static function intValueForStat4BoundaryRangeAudit(mixed $value): int
        {
            if (!is_int($value) || $value < 0) {
                throw new \InvalidArgumentException('SQLite next176 rowid must be a non-negative integer');
            }

            return $value;
        }

        private static function compareForStat4BoundaryRangeAudit(mixed $left, mixed $right, string $collation): int
        {
            $a = (string) $left;
            $b = (string) $right;
            if (strtoupper($collation) === 'NOCASE') {
                $a = strtolower($a);
                $b = strtolower($b);
            }

            return $a <=> $b;
        }

        private static function signatureForStat4BoundaryRangeAudit(mixed $value): string
        {
