                return self::compareValuesCurrentSourcePartialOrPayloadFence($whereLower, $term['right'] ?? null) >= 0;
            }
            if (in_array($operator, ['<=', '<'], true) && in_array($whereOperator, ['<=', '<', '=', 'BETWEEN'], true)) {
