                '=' => self::compareValuesCurrentSourcePartialOrPayloadFence($value, $term['right'] ?? null) === 0,
                '>=' => self::compareValuesCurrentSourcePartialOrPayloadFence($value, $term['right'] ?? null) >= 0,
                '>' => self::compareValuesCurrentSourcePartialOrPayloadFence($value, $term['right'] ?? null) > 0,
                '<=' => self::compareValuesCurrentSourcePartialOrPayloadFence($value, $term['right'] ?? null) <= 0,
                '<' => self::compareValuesCurrentSourcePartialOrPayloadFence($value, $term['right'] ?? null) < 0,
