                'upperBound' => $upper,
                'sampleRowids' => $sampleRowids,
                'gapRows' => $gapRows,
                'gapRowids' => array_map(static fn (array $row): int => $row['rowid'], $gapRows),
                'gapKeys' => $gapKeys,
                'anchoredSampleRowids' => $anchoredSampleRowids,
