                $satisfies = is_array($row) && self::rowSatisfiesTermsForSampleRowGuardFence($row, $whereTerms);
                $keyMatches = $rowKey !== null && $rowKey === $sampleKey;
                $ok = $satisfies && $keyMatches;
                if ($ok) {
                    $validated[] = $rowid;
                } else {
                    $rejected[] = $rowid;
                }
                $proofRows[] = [
                    'rowid' => $rowid,
                    'sampleKey' => $sampleKey,
                    'currentRowKey' => $rowKey,
                    'rowExists' => is_array($row),
                    'partialPredicateSatisfied' => $satisfies,
                    'sampleKeyMatchesCurrentRow' => $keyMatches,
                    'accepted' => $ok,
