        /** @param array<string,mixed> $source @return array<int,array<string,mixed>> */
        private static function rowMapForSampleRowGuardFence(array $source): array
        {
            $rows = $source['rows'] ?? null;
            if (!is_array($rows) || !array_is_list($rows)) {
