                if (in_array($operator, ['>', '>=', '<', '<='], true)) {
                    $comparison = strcmp(strtolower((string) $value), strtolower((string) ($term['right'] ?? '')));
                    if (($operator === '>' && $comparison <= 0)
                        || ($operator === '>=' && $comparison < 0)
                        || ($operator === '<' && $comparison >= 0)
                        || ($operator === '<=' && $comparison > 0)
