            }
            if (str_ends_with($pattern, '%') && !str_contains(substr($pattern, 0, -1), '_')) {
                return str_starts_with(strtolower($value), strtolower(substr($pattern, 0, -1)));
            }

            return strtolower($value) === strtolower($pattern);
        }

