                'nlt' => self::firstStatIntCurrentSourceStat4DensityVectorValidation($sample['nlt'] ?? null, 'nlt'),
                'ndlt' => self::firstStatIntCurrentSourceStat4DensityVectorValidation($sample['ndlt'] ?? null, 'ndlt'),
