         */
        private static function sampleHistogramProofCurrentSourceHistogramValidation(array $sample, array $rows): array
        {
            $key = $sample['key'];
            $blogId = $sample['blogId'];
            $sameKey = 0;
            $sameComposite = 0;
            $lessKey = 0;
            $lessComposite = 0;
            $distinctKeys = [];
            $distinctComposite = [];

            foreach ($rows as $row) {
                $rowKey = $row['expressionKey'];
                $rowBlog = $row['blogId'];
                if ($rowKey === $key) {
                    ++$sameKey;
                    if ($rowBlog === $blogId) {
                        ++$sameComposite;
                    }
                }
                if ($rowKey < $key) {
                    ++$lessKey;
                    $distinctKeys[$rowKey] = true;
                }
                if ($rowKey < $key || ($rowKey === $key && $rowBlog < $blogId)) {
                    ++$lessComposite;
                    $distinctComposite[$rowKey . "\0" . $rowBlog] = true;
                }
            }

            $expected = [
                'neq' => [$sameKey, $sameComposite],
                'nlt' => [$lessKey, $lessComposite],
                'ndlt' => [count($distinctKeys), count($distinctComposite)],
            ];
            $actual = [
                'neq' => $sample['neq'],
                'nlt' => $sample['nlt'],
                'ndlt' => $sample['ndlt'],
            ];

            return [
                'sampleKey' => $key,
                'sampleBlogId' => $blogId,
                'expected' => $expected,
                'actual' => $actual,
                'matchesCurrentHistogram' => $expected === $actual,
